def diff_tree(a, b, path=""):
    result = {}
    keys_a = set(a.keys())
    keys_b = set(b.keys())
    missing_in_a = keys_b - keys_a
    missing_in_b = keys_a - keys_b
    common_keys = keys_a & keys_b

    for key in common_keys:
        if isinstance(a[key], dict) and isinstance(b[key], dict):
            sub_path = f"{path}.{key}" if path else key
            result.update(diff_tree(a[key], b[key], sub_path))
        else:
            if a[key] == b[key]:
                continue
            result[f"{path}.{key}"] = [a[key], b[key]] if path else [a[key], b[key]]

    for key in missing_in_a:
        result[f"{path}.{key}"] = [a[key], None] if path else [a[key], None]

    for key in missing_in_b:
        result[f"{path}.{key}"] = [None, b[key]] if path else [None, b[key]]

    return result

