def unflatten(flat):
    def parse_key(key):
        if '[' in key:
            base_key, index = key.split('[')
            index = int(index[:-1])
            return base_key, index
        else:
            return key, None

    def build_dict(keys, value, d):
        if not keys:
            return value
        key, index = parse_key(keys[0])
        if index is not None:
            if key not in d:
                d[key] = [None] * (index + 1)
            d[key][index] = build_dict(keys[1:], value, d[key])
        else:
            if key not in d:
                d[key] = {}
            build_dict(keys[1:], value, d[key])
        return d

    result = {}
    for key, value in flat.items():
        build_dict(key.split('.'), value, result)
    return result

