def unflatten(flat):
    def build_path(path, key):
        if '.' in key:
            parent, _, child = key.rpartition('.')
            if parent not in path:
                path[parent] = {}
            build_path(path[parent], child)
        elif '[' in key:
            idx = key.split('[')[1].removesuffix(']')
            if key.removesuffix('[' + idx + ']') not in path:
                path[key.removesuffix('[' + idx + ']')] = [None] * (int(idx) + 1)
            path[key.removesuffix('[' + idx + ']')][int(idx)] = flat[key]

    result = {}
    for key, value in flat.items():
        build_path(result, key)
    return result

