#include <stdio.h>
#include <string.h>

char *int_to_roman(int n) {
    static char roman[16]; // 最多13个字符，如1000=M，3999=MMMCMXCIX
    memset(roman, 0, sizeof(roman)); // 清空字符串
    int values[] = {1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1};
    char *symbols[] = {"M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"};

    for (int i = 0; i < 13; i++) {
        while (n >= values[i]) {
            n -= values[i];
            strcat(roman, symbols[i]);
        }
    }
    return roman;
}

int main() {
    printf("%s\n", int_to_roman(1994)); // 输出: MCMXCIV
    return 0;
}

def merge_ranges(intervals):
    if not intervals:
        return []

    # 先按照区间的起始位置进行排序
    intervals.sort(key=lambda x: x[0])

    merged = [intervals[0]]

    for current in intervals[1:]:
        last_merged = merged[-1]

        # 检查当前区间是否与最后一个合并后的区间有重叠或相邻
        if current[0] <= last_merged[1]:
            # 更新合并后的区间的结束位置
            merged[-1] = [last_merged[0], max(last_merged[1], current[1])]
        else:
            # 否则将当前区间加入合并列表
            merged.append(current)

    return merged

