def merge_ranges(intervals):
    if not intervals:
        return []

    # 先按每个区间的起始位置进行排序
    intervals.sort(key=lambda x: x[0])

    merged = [intervals[0]]  # 初始化合并后的区间列表，包含第一个区间

    for current_start, current_end in intervals[1:]:
        last_end = merged[-1][1]

        # 如果当前区间的起始位置小于等于已合并区间的结束位置，则合并
        if current_start <= last_end:
            merged[-1][1] = max(last_end, current_end)
        else:
            merged.append([current_start, current_end])

    return merged

def eval_rpn(tokens):
    stack = []
    for token in tokens:
        if token.isdigit() or (token[0] == '-' and token[1:].isdigit()):
            stack.append(int(token))
        else:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                stack.append(int(a / b))
    return stack[0]

